#[allow(dead_code)]
pub fn emit_runtime_module(
    program: &Program,
    records: &BTreeMap<String, WasmRecord>,
    enums: &BTreeMap<String, WasmEnum>,
) -> Result<Vec<u8>, WasmError> {
    let sections = emit_runtime_sections(program, records, enums, 0)?;
    let mut code = CodeSection::new();
    for func in &sections.code_bodies {
        code.function(func);
    }
    let mut module = Module::new();
    module.section(&sections.types);
    module.section(&sections.imports);
    module.section(&sections.functions);
    module.section(&sections.memories);
    module.section(&sections.globals);
    module.section(&sections.exports);
    module.section(&code);
    Ok(module.finish())
}
